import{_ as e,o as a,c as r,a as o}from"./app.DLPSkIGI.js";const h=JSON.parse('{"title":"Autosync Troubleshooting Matrix","description":"","frontmatter":{},"headers":[],"relativePath":"reference/AUTOSYNC_TROUBLESHOOTING_MATRIX.md","filePath":"reference/AUTOSYNC_TROUBLESHOOTING_MATRIX.md","lastUpdated":1771803666000}'),i={name:"reference/AUTOSYNC_TROUBLESHOOTING_MATRIX.md"};function n(d,t,s,c,l,u){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="autosync-troubleshooting-matrix" tabindex="-1">Autosync Troubleshooting Matrix <a class="header-anchor" href="#autosync-troubleshooting-matrix" aria-label="Permalink to &quot;Autosync Troubleshooting Matrix&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Quick operator reference for common autosync failures across local workstream, GitHub, and Linear integrations.</p><h2 id="matrix" tabindex="-1">Matrix <a class="header-anchor" href="#matrix" aria-label="Permalink to &quot;Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely Cause</th><th>Diagnostics</th><th>Fix</th></tr></thead><tbody><tr><td>GitHub issue sync fails with 401/403</td><td>Missing/expired token or insufficient scopes</td><td>Check <code>thegent sync autopilot-status</code>; verify env/token source and scopes</td><td>Refresh token, re-run auth setup, verify repo/project permissions</td></tr><tr><td>Linear writes fail with auth error</td><td>Wrong team key or expired token</td><td>Check connector health output and auth source resolution</td><td>Rotate token and validate team/workspace binding</td></tr><tr><td>Items stuck in conflict queue</td><td>Local and remote changed same fields</td><td>Inspect conflict bundle + cycle artifacts</td><td>Apply conflict policy, resolve manually, re-run single cycle</td></tr><tr><td>Repeated retries with no progress</td><td>Connector degraded or rate limited</td><td>Review error classes and retry counters</td><td>Enable selective retry, increase backoff, pause degraded connector</td></tr><tr><td>Local status differs from remote after apply</td><td>Partial write or stale metadata</td><td>Compare cycle manifests and transition history log</td><td>Reconcile with replay from last good checkpoint</td></tr><tr><td>Missing remote item for local WL entry</td><td>Orphan mapping</td><td>Run orphan detection commands and mapping checks</td><td>Create/repair mapping, then sync</td></tr><tr><td>Missing local WL for remote item</td><td>Remote orphan not imported</td><td>Run remote-orphan scan</td><td>Import into WL namespace and attach ownership metadata</td></tr><tr><td>Sync loop too slow</td><td>Overloaded connector or high drift volume</td><td>Check cycle duration, batch size, queue depth</td><td>Reduce batch size, isolate connector, tune interval policy</td></tr><tr><td>HTML/report artifacts expose sensitive fields</td><td>Missing redaction policy</td><td>Inspect generated artifact fields</td><td>Apply redaction policy pack and regenerate artifacts</td></tr></tbody></table><h2 id="standard-diagnostic-sequence" tabindex="-1">Standard Diagnostic Sequence <a class="header-anchor" href="#standard-diagnostic-sequence" aria-label="Permalink to &quot;Standard Diagnostic Sequence&quot;">​</a></h2><ol><li><code>thegent sync work-stream</code></li><li><code>thegent sync autopilot --once</code></li><li><code>thegent sync autopilot-status</code></li><li>Inspect latest cycle artifacts and conflict queue</li><li>Apply targeted remediation, then re-run single-cycle sync</li></ol><h2 id="escalation-rules" tabindex="-1">Escalation Rules <a class="header-anchor" href="#escalation-rules" aria-label="Permalink to &quot;Escalation Rules&quot;">​</a></h2><ul><li>Escalate immediately for auth failures across multiple connectors.</li><li>Escalate if conflict queue grows for 3 consecutive cycles.</li><li>Escalate if state divergence persists after a checkpoint restore verification.</li></ul>',9)])])}const m=e(i,[["render",n]]);export{h as __pageData,m as default};
